def connected_components(n, adj, edge_subset):
    """Count number of connected components considering only edge_subset as edges."""
    visited = [False] * (n + 1)
    count = 0

    # Mark vertices incident to edge_subset
    for u, v in edge_subset:
        visited[u] = True
        visited[v] = True

    # BFS/DFS to count components
    for start in range(1, n + 1):
        if not visited[start]:
            count += 1
            visited[start] = True
            stack = [start]
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
    return count

def neary2(n):
