def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    def check(arr):
        remaining = 0
        for x in arr:
            if remaining > x:
                return False
            remaining = x - remaining
        return remaining == 0

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1
        a = list(map(int, lines[idx].split()))
        idx += 1

        if check(a):
            results.append('YES')
            continue

        for i in range(n - 1):
            a[i], a[i + 1] = a[i + 1], a[i]
            if check(a):
                results.append('YES')
            a[i], a[i + 1] = a[i + 1], a[i]

        results.append('NO')

    return '\n'.join(results)


