def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.isqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def get_prime_factors(n):
    factors = set()
    d = 2
    n_temp = n
    while d * d <= n_temp:
        while n_temp % d == 0:
            factors.add(d)
            n_temp //= d
        d += 1
    if n_temp > 1:
        factors.add(n_temp)
    return list(factors)

def mod_pow(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def is_primitive_root(g, p, n):
    for q in get_prime_factors(n):
        if mod_pow(g, n // q, p) == 1:
            return False
    return True

