MOD = 998244353

def count_perms_with_forb(n, forbidden):
    """
    Count permutations p of 1..n such that p[i] != forbidden[i] for forbidden[i] != -1.
    Uses inclusion-exclusion principle.
    """
    count = 0
    m = len(forbidden)
    # Count how many conflict positions have at least k additional forbidden values
    from itertools import combinations

    for k in range(m + 1):
        conflicts = []
        for i in range(m):
            if forbidden[i] == -1:
                continue
            conflicts.append(forbidden[i])

        count_k = 0
        for combo in combinations(conflicts, k):
            count_k += 1

        term = fact[n - k] * count_k
        if k % 2 == 1:
            count = (count - term) % MOD
        else:
            count = (count + term) % MOD

    return count

