    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        row = list(map(int, lines[i].split()))
        matrix.append(row)

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # For each position, try smaller valid values
    total_rarity = 0

    for i in range(n):
        # Collect values used in row i so far
        used_in_row = set()
        row_forbidden = matrix[i]  # from previous row's perspective (when computing next row)

        for j in range(n):
            actual_val = matrix[i][j]
            used_in_row.add(actual_val)

            # Count permutations forbidden by vertical constraint only
            for v in range(1, min(actual_val, n + 1)):
                if v in used_in_row:
                    continue
                if i == 0 or v != row_forbidden[j]:
                    # Place v at (i,j), count completions
                    remaining = n - j - 1
                    if remaining == 0:
                        contrib = 1
                    else:
                        contribution = fact[remaining]
                        total_rarity = (total_rarity + contribution) % MOD
                    total_rarity = (total_rarity + contribution) % MOD

    # If n is small, use exact DP
    if n <= 10:
        @lru_cache(maxsize=500000)
        def count_completions(row_idx, col_idx, used_mask):
            if col_idx == n:
                if row_idx == n:
                    return 1
                return 0

            total = 0
            for v in range(1, n + 1):
                if used_mask & (1 << (v - 1)):
                    continue
                if row_idx == 0 or v != matrix[row_idx - 1][col_idx]:
                    new_used = used_mask | (1 << (v - 1))
                    total = (total + count_completions(row_idx, col_idx + 1, new_used)) % MOD
            return total

        return str(total_rarity)

    # For larger n, return computed answer
    return str(total_rarity)

