import sys

def manhattan(p1, p2):
    """Manhattan distance between two points."""
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def get_arrival_time(gathering_point, dwarf, stations):
    """
    Get minimum time for a dwarf to reach gathering point.
    Can go direct or via subway.
    """
    # Direct walking
    direct = manhattan(gathering_point, dwarf)

    # Via subway: walk to nearest station, then from station to gathering point
    subway = float('inf')
    for station in stations:
        walk_to_station = manhattan(dwarf, station)
        walk_from_station = manhattan(station, gathering_point)
        subway = min(subway, walk_to_station + walk_from_station)

    return min(direct, subway)

def get_max_gathering_time(gathering_point, all_dwarves, all_stations):
    """Get the maximum time any dwarf takes to reach the gathering point."""
    max_time = 0
    for dwarf in all_dwarves:
        t = get_arrival_time(gathering_point, dwarf, all_stations)
        if t > max_time:
            max_time = t
    return max_time

