def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    # Compute initial GCD
    g = a[0]
    for i in range(1, n):
        g = math.gcd(g, a[i])

    if g == 1:
        return "0\n"

    # Get prime factors of g
    prime_factors = []
    d = 2
    temp = g
    while d * d <= temp:
        if temp % d == 0:
            prime_factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        prime_factors.append(temp)

    p_count = len(prime_factors)
    full_mask = (1 << p_count) - 1

    # Group judges by mask, keep min e for each
    min_e = {}
    for i in range(n):
        mask = 0
        for j, p in enumerate(prime_factors):
            if p <= k and (a[i] % p == 0):
                mask |= (1 << j)

        if mask not in min_e or e[i] < min_e[mask]:
            min_e[mask] = e[i]

    # Check coverage
    combined = 0
    for mask in min_e:
        combined |= mask
    if combined != full_mask:
        return "-1\n"

    # Sort masks by experience
    sorted_masks = sorted([(mask, exp) for mask, exp in min_e.items()], key=lambda x: x[1])

    # Find minimum cost using the insight that we can try small counts first
    min_cost = float('inf')

    def backtrack(idx, current_mask, count, current_sum):
        nonlocal min_cost

        if current_mask == full_mask:
            cost = count * current_sum
            if cost < min_cost:
                min_cost = cost
            return

        # Pruning: if current partial score already exceeds min_cost, prune
        if min_cost != float('inf') and count * current_sum >= min_cost:
            return

        if idx >= len(sorted_masks):
            return

        (mask, exp) = sorted_masks[idx]

        # Skip this judge if adding would make cost invalid
        new_sum = current_sum + exp

        # Pruning based on minimum possible additional judges needed
        if count * new_sum >= min_cost:
            backtrack(idx + 1, current_mask, count, current_sum)
            backtrack(idx + 1, current_mask | mask, count + 1, new_sum)
        else:
            # Take this judge for potential better solution
            new_mask = current_mask | mask
            backtrack(idx + 1, new_mask, count + 1, new_sum)

    backtrack(0, 0, 0, 0)

    if min_cost == float('inf'):
        return "-1\n"
    else:
        return str(min_cost) + "\n"

