        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)

    # Tarjan's SCC algorithm
    index_counter = [0]
    stack = []
    lowlink = [0] * (n + 1)
    index = [None] * (n + 1)
    on_stack = [False] * (n + 1)
    sccs = []

    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w in adj[v]:
            if index[w] is None:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack[w]:
                lowlink[v] = min(lowlink[v], index[w])

        if lowlink[v] == index[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for i in range(1, n + 1):
        if index[i] is None:
            strongconnect(i)

    # Map vertices to SCCs
    vertex_to_scc = [0] * (n + 1)
    scc_counter = 0
    scc_sizes = []
    for scc in sccs:
