    def all_blocks_equal(r, c):
        """Check if all r×c blocks in the matrix are equal"""
        first_block = (1, 1)
        all_blocs = get_block_locs(r, c)

        for i in range(1, len(all_blocs)):
            curr = all_blocs[i]
            if r == 1 and c == 1:
                # For 1x1 blocks, compare individual cells
                if matrix[first_block[0]-1][first_block[1]-1] != matrix[curr[0]-1][curr[1]-1]:
                    return False
            else:
                # Compare full blocks
                def extract_block(start):
                    vals = []
