                            vals.append(matrix[start[0]-1 + di][start[1]-1 + dj])
                    return tuple(vals)
                if extract_block((1, 1)) != extract_block(curr):
                    return False
        return True

    # Find all valid (r, c) pairs
    count = 0
    valid_pairs = []
    for r in n_divs:
        for c in m_divs:
            if all_blocks_equal(r, c):
                count += 1
                valid_pairs.append((r, c))

