import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, u, r = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = tuple(map(int, lines[2].split()))
    k = tuple(map(int, lines[3].split()))
    p = tuple(int(x) - 1 for x in lines[4].split())  # Convert to 0-indexed

    # Increase recursion limit for depth up to 30 with branching
    sys.setrecursionlimit(50000)

    @lru_cache(maxsize=None)
    def dp(state_tuple, u_left):
        if u_left == 0:
            return sum(b[i] * state_tuple[i] for i in range(n))

        # Operation 1: XOR with k[i] for all i
        op1 = tuple(state_tuple[i] ^ k[i] for i in range(n))

        # Operation 2: a[i] = old_a[p[i]] + r (permutation + add)
        op2 = tuple(state_tuple[p[i]] + r for i in range(n))

        return max(dp(op1, u_left - 1), dp(op2, u_left - 1))

    initial_state = tuple(a)
    return str(dp(initial_state, u))

